const resultArea = document.getElementById('result-area');
const hand = [{ keyword: 'Card', description: 'Description' }];
function saveImage() {
  const memos = [];
  resultArea.querySelectorAll('textarea').forEach(ta => {
    memos.push(ta.value.trim());
  });
  const container = document.createElement('div');
  let cardsHtml = '';
  hand.forEach((card, i) => {
    const memo = memos[i] || '';
    cardsHtml += `
      <div>${escapeHtml(card.keyword)} ${escapeHtml(card.description)}
        ${memo ? `<p>${escapeHtml(memo)}</p>` : ''}
      </div>
    `;
  });
  container.innerHTML = `
    ${cardsHtml}
  `;
}

